#!/usr/bin/env python3
r"""
prolong.py --- the Cartan prolong over F_2 inside vect(m; N), block by
(degree, weight), and the analysis of the result:

  * dim / sdim of every component,
  * the ideal J generated by g_{-1} (the would-be simple core) and a proof of
    its simplicity by the graded criterion (see `simple_test`),
  * the super-closure (odd squares) and the restricted closure (all squares).

Everything is exact over F_2.
"""
import sys
import time
from collections import defaultdict

from f2vf import Space, Echelon, kernel_bits, find_weights


def log(*a):
    print(*a, flush=True)


class Graded:
    """A graded subalgebra of vect(m;N), stored as {deg: {wt: Echelon}}."""

    def __init__(self, sp):
        self.sp = sp
        self.comp = defaultdict(dict)

    def block(self, dg, wt):
        b = self.comp[dg].get(wt)
        if b is None:
            b = self.comp[dg][wt] = Echelon()
        return b

    def add(self, v):
        """add a homogeneous field; returns True if new"""
        v = set(v)
        if not v:
            return False
        k0 = next(iter(v))
        dg, wt = self.sp.kdeg(k0), self.sp.kwt(k0)
        return self.block(dg, wt).add(v)

    def reduce(self, v):
        v = set(v)
        if not v:
            return v
        # v may be non-homogeneous: split
        parts = defaultdict(set)
        for k in v:
            parts[(self.sp.kdeg(k), self.sp.kwt(k))].add(k)
        out = set()
        for (dg, wt), p in parts.items():
            b = self.comp.get(dg, {}).get(wt)
            out |= b.reduce(p) if b is not None else p
        return out

    def contains(self, v):
        return not self.reduce(v)

    def dim(self, dg=None):
        if dg is None:
            return sum(self.dim(d) for d in self.comp)
        return sum(len(b) for b in self.comp.get(dg, {}).values())

    def degrees(self):
        return sorted(d for d in self.comp if self.dim(d))

    def basis(self, dg=None):
        out = []
        for d in ([dg] if dg is not None else self.degrees()):
            for b in self.comp.get(d, {}).values():
                out.extend(b.basis())
        return out

    def sdim(self, dg=None):
        ev = od = 0
        for v in self.basis(dg):
            # parity of a homogeneous (in parity) element; our blocks are
            # parity-homogeneous only if the weight lattice sees parity,
            # so count via a parity-split echelon instead
            pass
        return self.parity_dims(dg)

    def parity_dims(self, dg=None):
        """dims of the even and odd parts: the space is split by parity of keys
        if every basis vector is parity-homogeneous; otherwise compute the
        parity-homogeneous components by intersecting."""
        sp = self.sp
        ev = od = 0
        for d in ([dg] if dg is not None else self.degrees()):
            for b in self.comp.get(d, {}).values():
                E0, E1 = Echelon(), Echelon()
                homog = True
                for v in b.basis():
                    ps = {sp.kpar(k) for k in v}
                    if len(ps) > 1:
                        homog = False
                        break
                if homog:
                    for v in b.basis():
                        if sp.kpar(next(iter(v))) == 0:
                            ev += 1
                        else:
                            od += 1
                else:
                    # the projections to the two parities; the block is
                    # parity-graded iff both projections lie in it
                    B = b.basis()
                    for v in B:
                        v0 = {k for k in v if sp.kpar(k) == 0}
                        v1 = v - v0
                        assert b.contains(v0) and b.contains(v1), 'block not parity-graded'
                        E0.add(v0)
                        E1.add(v1)
                    ev += len(E0)
                    od += len(E1)
        return ev, od


def group_monofields(sp, dg, weighted=True):
    """all monomial fields x^A d_i of degree dg, grouped by weight"""
    out = defaultdict(list)
    for i in range(sp.m):
        md = dg + sp.degs[i]
        for A in monos_deg(sp, md):
            k = (A << 5) | i
            wt = sp.kwt(k) if weighted else ()
            out[wt].append(k)
    return out


def monos_deg(sp, d):
    """packed monomials of weighted degree d (lazy, memoized)"""
    memo = sp.__dict__.setdefault('_mdmemo', {})
    if d in memo:
        return memo[d]
    if d < 0:
        return []
    # suffix DP: monomials in coordinates i..m-1 of degree e
    tab = sp.__dict__.setdefault('_mdtab', {})

    def rec(i, e):
        key = (i, e)
        r = tab.get(key)
        if r is not None:
            return r
        if i == sp.m:
            r = [0] if e == 0 else []
        else:
            r = []
            for a in range(1 << sp.h[i]):
                ee = e - a * sp.degs[i]
                if ee < 0:
                    break
                for B in rec(i + 1, ee):
                    r.append(B | (a << sp.off[i]))
        tab[key] = r
        return r
    memo[d] = rec(0, d)
    return memo[d]


def maxmonodeg(sp):
    return sum(((1 << h) - 1) * dg for h, dg in zip(sp.h, sp.degs))


def prep_monos(sp):
    pass


def prolong(sp, neg, g0=None, maxdeg=None, verbose=True, stop_at=None, g1=None, prune=True):
    """neg: list of fields spanning g_- (homogeneous);
       g0: list of fields generating g_0 (as a Lie algebra), or None for the
           complete prolong of g_-.
       Returns a Graded."""
    t0 = time.time()
    G = Graded(sp)
    for X in neg:
        assert len({sp.kdeg(k) for k in X}) == 1, 'inhomogeneous degree'
        assert len({sp.kwt(k) for k in X}) == 1, 'inhomogeneous weight'
        assert sp.kdeg(next(iter(X))) < 0
        G.add(X)
    # g_- closed?
    nb = G.basis()
    for a in nb:
        for b in nb:
            c = sp.bracket(a, b)
            assert G.contains(c), 'g_- not closed'
    gm1 = G.basis(-1)
    # generated by g_{-1}?
    H = Graded(sp)
    for x in gm1:
        H.add(x)
    changed = True
    while changed:
        changed = False
        for a in gm1:
            for b in H.basis():
                if H.add(sp.bracket(a, b)):
                    changed = True
    if H.dim() != G.dim():
        log('  NOTE: g_- is not generated by g_{-1} (%d vs %d); using all of g_-' % (H.dim(), G.dim()))
        conds = G.basis()
    else:
        conds = gm1
    cond_info = [(X, sp.kdeg(next(iter(X))), sp.kwt(next(iter(X)))) for X in conds]
    # coordinates e whose field d_e itself lies in g_- (a bare derivative): then
    # [d_e, D] has no cancellation, which prunes the unknowns (heights 1 only)
    pure = []
    if all(hh == 1 for hh in sp.h):
        for i in range(sp.m):
            if G.contains({(0 << 5) | i}):
                pure.append(i)
    nonpure = [i for i in range(sp.m) if i not in pure]
    if verbose:
        log('  g_-: dims', {d: G.dim(d) for d in G.degrees()})
    start = 0
    if g0 is not None:
        for X in g0:
            assert len({sp.kdeg(k) for k in X}) == 1 and sp.kdeg(next(iter(X))) == 0
            assert len({sp.kwt(k) for k in X}) == 1, 'g0 generator inhomogeneous in weight'
            G.add(X)
        # close under bracket
        changed = True
        while changed:
            changed = False
            B = G.basis(0)
            for a in B:
                for b in B:
                    if G.add(sp.bracket(a, b)):
                        changed = True
        for a in G.basis(0):
            for b in G.basis():
                if sp.kdeg(next(iter(b))) < 0:
                    assert G.contains(sp.bracket(a, b)), 'g0 does not preserve g_-'
        start = 1
        if verbose:
            log('  g_0 given: dim', G.dim(0))
        if g1 is not None:
            for X in g1:
                G.add(X)
            start = 2
            if verbose:
                log('  g_1 given: dim', G.dim(1))
    topdeg = maxmonodeg(sp)
    k = start
    while True:
        if maxdeg is not None and k > maxdeg:
            break
        if k > topdeg:
            break
        if prune and pure:
            blocks = pruned_blocks(sp, G, k, pure, nonpure)
        else:
            blocks = group_monofields(sp, k)
        found = 0
        for wt, unknowns in blocks.items():
            # images
            imgs = []
            idx = {}
            for u in unknowns:
                v = 0
                for ci, (X, xd, xw) in enumerate(cond_info):
                    img = sp.bracket(X, {u})
                    if not img:
                        continue
                    r = G.reduce(img)
                    for kk in r:
                        key = (ci, kk)
                        j = idx.get(key)
                        if j is None:
                            j = idx[key] = len(idx)
                        v |= 1 << j
                imgs.append(v)
            ker = kernel_bits(imgs)
            for c in ker:
                D = set()
                j = 0
                while c:
                    if c & 1:
                        D.add(unknowns[j])
                    c >>= 1
                    j += 1
                G.add(D)
                found += 1
        if verbose:
            log('  g_%d: dim %d   (%.1fs)' % (k, found, time.time() - t0))
        if found == 0:
            break
        if stop_at is not None and k >= stop_at:
            break
        k += 1
    return G


# ------------------------------------------------------------ analysis
def generators(G):
    """a set of homogeneous elements generating G as a Lie algebra: start with
    all of g_{<=1}, then add, degree by degree, what is not generated."""
    sp = G.sp
    gens = [v for d in G.degrees() if d <= 1 for v in G.basis(d)]
    S = subalgebra(sp, gens)
    for d in G.degrees():
        if d <= 1:
            continue
        added = False
        for v in G.basis(d):
            if not S.contains(v):
                gens.append(v)
                S.add(v)
                added = True
        if added:
            S = subalgebra(sp, gens)
    assert S.dim() == G.dim()
    return gens


def subalgebra(sp, gens, S=None):
    if S is None:
        S = Graded(sp)
    queue = []
    for g in gens:
        if S.add(g):
            queue.append(set(g))
    # close: bracket every new element with every generator and every basis elt
    allb = S.basis()
    while queue:
        v = queue.pop()
        for g in gens:
            w = sp.bracket(g, v)
            w = S.reduce(w)
            if w:
                S.add(w)
                queue.append(w)
    return S


def ad_closure(sp, gens, seed, extra=None):
    """the smallest subspace containing `seed` and stable under ad(g), g in gens
    (the ideal generated by seed, if gens generate the algebra).  `extra`:
    an optional function v -> list of further vectors to include (e.g. squares)."""
    J = Graded(sp)
    queue = []
    for s in seed:
        r = J.reduce(s)
        if r:
            J.add(r)
            queue.append(r)
    while queue:
        v = queue.pop()
        cands = [sp.bracket(g, v) for g in gens]
        if extra is not None:
            cands += extra(v)
        for w in cands:
            r = J.reduce(w)
            if r:
                J.add(r)
                queue.append(r)
    return J


def restricted_closure(sp, L, gens=None):
    """p-envelope of L inside vect(m;1): L + span of iterated squares of its
    basis; closed under brackets automatically (Jacobson)."""
    R = Graded(sp)
    for v in L.basis():
        R.add(v)
    queue = list(L.basis())
    while queue:
        v = queue.pop()
        s = sp.square(v)
        r = R.reduce(s)
        if r:
            R.add(r)
            queue.append(r)
    return R


def is_subalgebra(sp, L):
    B = L.basis()
    for a in B:
        for b in B:
            if not L.contains(sp.bracket(a, b)):
                return False
    return True


def burnside_irreducible(sp, g0basis, gm1basis):
    """absolute irreducibility of g_{-1} under g_0 over F_2: the associative
    algebra generated by the operators ad(x)|g_{-1} is all of End(g_{-1})."""
    n = len(gm1basis)
    E = Echelon()
    for v in gm1basis:
        E.add(v)
    # coordinates in the basis gm1basis: solve by reduction with tracking
    piv = {}
    order = []
    for idx, v in enumerate(gm1basis):
        c = 1 << idx
        v = set(v)
        while v:
            p = max(v)
            if p in piv:
                v ^= piv[p][0]
                c ^= piv[p][1]
            else:
                piv[p] = (v, c)
                break
        else:
            raise ValueError('dependent basis')

    def coords(w):
        w = set(w)
        c = 0
        while w:
            p = max(w)
            b = piv.get(p)
            if b is None:
                raise ValueError('not in g_-1')
            w ^= b[0]
            c ^= b[1]
        return c

    mats = []
    for x in g0basis:
        cols = [coords(sp.bracket(x, e)) for e in gm1basis]
        # matrix as int of n*n bits: entry (r,c) at bit r*n+c
        M = 0
        for c, col in enumerate(cols):
            r = 0
            while col:
                if col & 1:
                    M |= 1 << (r * n + c)
                col >>= 1
                r += 1
        mats.append(M)

    def mul(A, B):
        C = 0
        for r in range(n):
            row = (A >> (r * n)) & ((1 << n) - 1)
            acc = 0
            c = 0
            while row:
                if row & 1:
                    acc ^= (B >> (c * n)) & ((1 << n) - 1)
                row >>= 1
                c += 1
            C |= acc << (r * n)
        return C

    from f2vf import BitEchelon
    I = 0
    for r in range(n):
        I |= 1 << (r * n + r)
    A = BitEchelon()
    A.add(I)
    basis = [I]
    frontier = [I]
    while frontier:
        nf = []
        for X in frontier:
            for M in mats:
                Y = mul(M, X)
                if A.add(Y):
                    basis.append(Y)
                    nf.append(Y)
        frontier = nf
        if len(A) == n * n:
            break
    return len(A) == n * n, len(A)


def simple_test(sp, J, verbose=True):
    """Graded criterion for the simplicity (over the algebraic closure) of a
    finite-dimensional graded Lie algebra J = sum J_i, J_{-1} != 0:
      (a) J_- is generated by J_{-1} and J is transitive (no x in J_{>=0} with
          [x, J_{-1}] = 0);
      (b) J_{-1} is an absolutely irreducible J_0-module;
      (c) for every i <= -2, no nonzero x in J_i commutes with all of J_{>=1};
      (d) the ideal of J generated by J_{-1} is J.
    Then every nonzero graded ideal is J, and so is every ideal (its initial
    forms span a graded ideal of the same dimension)."""
    degs = J.degrees()
    gm1 = J.basis(-1)
    out = {}
    # (a) transitivity
    ok_a = True
    for d in degs:
        if d < 0:
            continue
        B = J.basis(d)
        # kernel of x -> ([x, e])_e on J_d
        imgs = []
        idx = {}
        for x in B:
            v = 0
            for ci, e in enumerate(gm1):
                for kk in sp.bracket(x, e):
                    key = (ci, kk)
                    j = idx.setdefault(key, len(idx))
                    v ^= 1 << j
            imgs.append(v)
        if kernel_bits(imgs):
            ok_a = False
    out['transitive'] = ok_a
    # (b)
    irr, dA = burnside_irreducible(sp, J.basis(0), gm1)
    out['g-1 abs. irreducible'] = irr
    # (c)
    ok_c = True
    pos = [v for d in degs if d >= 1 for v in J.basis(d)]
    for d in degs:
        if d > -2:
            continue
        B = J.basis(d)
        imgs = []
        idx = {}
        for x in B:
            v = 0
            for ci, y in enumerate(pos):
                for kk in sp.bracket(x, y):
                    j = idx.setdefault((ci, kk), len(idx))
                    v ^= 1 << j
            imgs.append(v)
        if kernel_bits(imgs):
            ok_c = False
    out['no low annihilated'] = ok_c
    # (d)
    gens = generators(J)
    I = ad_closure(sp, gens, gm1)
    out['ideal(J_-1)=J'] = (I.dim() == J.dim())
    out['simple'] = all(out.values())
    return out


def support(G, dg):
    s = set()
    for b in G.comp.get(dg, {}).values():
        for v in b.piv.values():
            s |= v
    return s


def pruned_blocks(sp, G, k, pure, nonpure):
    """candidate unknowns of degree k: every term x^S d_i of a solution satisfies,
    for every 'pure' coordinate e in S, x^{S-e} d_i in supp(G_{k - deg e})."""
    sup = {}
    for e in pure:
        dd = k - sp.degs[e]
        if dd not in sup:
            sup[dd] = support(G, dd)
    cands = set()
    # monomials purely in the non-pure coordinates
    npmask = 0
    for i in nonpure:
        npmask |= sp.mask[i]
    for i in range(sp.m):
        md = k + sp.degs[i]
        for A in monos_deg_sub(sp, md, nonpure):
            cands.add((A << 5) | i)
    for e in pure:
        for kk in sup[k - sp.degs[e]]:
            A, i = kk >> 5, kk & 31
            if A & sp.mask[e]:
                continue
            cands.add(((A | sp.one[e]) << 5) | i)
    out = defaultdict(list)
    for kk in cands:
        A, i = kk >> 5, kk & 31
        ok = True
        for e in pure:
            if A & sp.mask[e]:
                if (((A ^ sp.one[e]) << 5) | i) not in sup[k - sp.degs[e]]:
                    ok = False
                    break
        if ok and sp.kdeg(kk) == k:
            out[sp.kwt(kk)].append(kk)
    return out


def monos_deg_sub(sp, d, coords):
    """packed monomials of degree d in the given coordinates only (heights 1)"""
    key = ('sub', d, tuple(coords))
    memo = sp.__dict__.setdefault('_mdmemo', {})
    if key in memo:
        return memo[key]
    res = []

    def rec(j, e, A):
        if e == 0:
            res.append(A)
            return
        if j == len(coords):
            return
        c = coords[j]
        rec(j + 1, e, A)
        if sp.degs[c] <= e:
            rec(j + 1, e - sp.degs[c], A | sp.one[c])
    if d >= 0:
        rec(0, d, 0)
    memo[key] = res
    return res
